// Guest (anonymous) sign-in for Supabase — NOT generated by Figma Make.
import { useCallback, useEffect, useState } from "react";
import type { User } from "@supabase/supabase-js";
import { supabase } from "./supabase";

export type GuestAuthStatus = "loading" | "ready" | "unavailable";

export type GuestAuth = {
  status: GuestAuthStatus;
  user: User | null;
  /** From auth user_metadata.name (what get_study_leaderboard shows). Empty until the user picks one. */
  displayName: string;
  setDisplayName: (name: string) => Promise<boolean>;
  /** Friendly reason when status is "unavailable". */
  reason: string;
};

// One shared sign-in promise so React StrictMode's double effects don't create two guest users.
let sessionPromise: Promise<{ user: User | null; reason: string }> | null = null;

export function ensureGuestSession() {
  if (!supabase) return Promise.resolve({ user: null, reason: "Supabase isn't configured — using sample data." });
  sessionPromise ??= (async () => {
    const { data } = await supabase.auth.getSession();
    if (data.session?.user) return { user: data.session.user, reason: "" };
    const { data: signIn, error } = await supabase.auth.signInAnonymously();
    if (error || !signIn.user) {
      console.warn("[supabase] guest sign-in failed:", error);
      const reason =
        error?.code === "anonymous_provider_disabled"
          ? "Guest sign-in is off in Supabase — showing local data only."
          : "Couldn't connect to Study Hopper's server — showing local data only.";
      return { user: null, reason };
    }
    return { user: signIn.user, reason: "" };
  })().catch((error) => {
    console.warn("[supabase] guest sign-in crashed:", error);
    sessionPromise = null;
    return { user: null, reason: "Couldn't connect to Study Hopper's server — showing local data only." };
  });
  return sessionPromise;
}

export function useGuestAuth(): GuestAuth {
  const [status, setStatus] = useState<GuestAuthStatus>(supabase ? "loading" : "unavailable");
  const [user, setUser] = useState<User | null>(null);
  const [reason, setReason] = useState(supabase ? "" : "Supabase isn't configured — using sample data.");

  useEffect(() => {
    let alive = true;
    ensureGuestSession().then((result) => {
      if (!alive) return;
      setUser(result.user);
      setReason(result.reason);
      setStatus(result.user ? "ready" : "unavailable");
    });
    const sub = supabase?.auth.onAuthStateChange((_event, session) => {
      if (alive && session?.user) setUser(session.user);
    });
    return () => {
      alive = false;
      sub?.data.subscription.unsubscribe();
    };
  }, []);

  const setDisplayName = useCallback(async (name: string) => {
    const trimmed = name.trim().slice(0, 40);
    if (!supabase || !trimmed) return false;
    const { data, error } = await supabase.auth.updateUser({ data: { name: trimmed, display_name: trimmed } });
    if (error) {
      console.warn("[supabase] couldn't save display name:", error);
      return false;
    }
    if (data.user) setUser(data.user);
    return true;
  }, []);

  const displayName = String(user?.user_metadata?.name ?? "").trim();
  return { status, user, displayName, setDisplayName, reason };
}
